function stripPolishDiacritics(text) {
	const map = {
		ą: "a",
		ć: "c",
		ę: "e",
		ł: "l",
		ń: "n",
		ó: "o",
		ś: "s",
		ź: "z",
		ż: "z",
		Ą: "A",
		Ć: "C",
		Ę: "E",
		Ł: "L",
		Ń: "N",
		Ó: "O",
		Ś: "S",
		Ź: "Z",
		Ż: "Z"
	};
	return text.replace(/[ąćęłńóśźżĄĆĘŁŃÓŚŹŻ]/g, (ch) => map[ch] || ch);
}
export function exportTechnicalDocsPdf(projectName, docData, objects, logicNodes, mobileConfig) {
	const pdf = new jsPDF({
		unit: "mm",
		format: "a4"
	});
	let y = 18;
	const writeLine = (txt, size = 10, bold = false) => {
		if (y > 272) {
			pdf.addPage();
			y = 18;
		}
		pdf.setFont("helvetica", bold ? "bold" : "normal");
		pdf.setFontSize(size);
		const clean = stripPolishDiacritics(txt);
		const lines = pdf.splitTextToSize(clean, 175);
		pdf.text(lines, 16, y);
		y += lines.length * (size * .45) + 3;
	};
	writeLine(`VORTEXVR STUDIO - TECHNICAL SPECIFICATION REPORT`, 15, true);
	writeLine(`Project: ${projectName} | Generated: ${new Date().toISOString().slice(0, 16)}`, 9, false);
	writeLine(`Version: ${docData?.version || "v2.4.0-E2EE"}`, 9, false);
	y += 3;
	writeLine(`1. EXECUTIVE SUMMARY`, 12, true);
	writeLine(docData?.executiveSummary || "Cross-platform VR & Mobile 3D interactive scene.", 10, false);
	writeLine(`2. 3D SCENE ARCHITECTURE & COMPOSITE ACTORS (${objects.length})`, 12, true);
	writeLine(docData?.sceneArchitecture || "ACES Filmic PBR pipeline with PMREM RoomEnvironment.", 10, false);
	objects.forEach((obj, idx) => {
		writeLine(`   [${idx + 1}] ${obj.name} (${obj.type}) - Pos: [${obj.position.map((n) => n.toFixed(1)).join(", ")}] | Parts: ${obj.partsCount} | Tris: ${obj.triangles} | Anim: ${obj.animation.trajectoryType}`, 9, false);
	});
	y += 2;
	writeLine(`3. NO-CODE LOGIC PIPELINES (${logicNodes.length})`, 12, true);
	logicNodes.forEach((ln, idx) => {
		writeLine(`   [${idx + 1}] ${ln.name}: IF ${ln.event} -> THEN ${ln.action} (Active: ${ln.enabled ? "YES" : "NO"})`, 9, false);
	});
	y += 2;
	writeLine(`4. STANDALONE PHONE & TABLET CONFIGURATION (HEADSET-FREE)`, 12, true);
	writeLine(`   Control Mode: ${mobileConfig.controlScheme} | IPD: ${mobileConfig.ipdMm}mm | FOV: ${mobileConfig.fovDegrees} deg | Target FPS: ${mobileConfig.targetFps}Hz | Render Scale: ${mobileConfig.adaptiveResolutionPct}%`, 9, false);
	writeLine(docData?.mobileCompatGuide || "", 9, false);
	y += 2;
	writeLine(`5. E2EE SECURITY & QA CHECKLIST`, 12, true);
	writeLine(docData?.securityAndCloudNotes || "AES-256-GCM End-to-End Encrypted Cloud Sync.", 9, false);
	(docData?.qaChecklist || []).forEach((item) => {
		writeLine(`   [x] ${item}`, 9, false);
	});
	pdf.save(`${projectName.toLowerCase().replace(/\s+/g, "_")}_tech_docs.pdf`);
}
